# ============================================================
# 1. REGISTRY PATTERN — Auto-register classes/functions
# ============================================================
class HandlerRegistry:
    _handlers = {}

    @classmethod
    def register(cls, name):
        def decorator(handler_cls):
            cls._handlers[name] = handler_cls
            return handler_cls
        return decorator

    @classmethod
    def get(cls, name):
        return cls._handlers.get(name)

@HandlerRegistry.register("csv")
class CSVHandler:
    def parse(self, data): return "Parsing CSV"

@HandlerRegistry.register("json")
class JSONHandler:
    def parse(self, data): return "Parsing JSON"

handler = HandlerRegistry.get("csv")()
print(handler.parse("data"))

# ============================================================
# 2. NULL OBJECT PATTERN — Avoid None checks
# ============================================================
class NullLogger:
    """Does nothing — safe replacement for None."""
    def info(self, *args, **kwargs): pass
    def error(self, *args, **kwargs): pass
    def debug(self, *args, **kwargs): pass

class Service:
    def __init__(self, logger=None):
        self.logger = logger or NullLogger()

    def process(self):
        self.logger.info("Processing...")  # Never crashes!

# ============================================================
# 3. MIXIN PATTERN — Reusable behavior through multiple inheritance
# ============================================================
import json

class SerializableMixin:
    def to_json(self):
        return json.dumps(self.__dict__)

    def to_dict(self):
        return self.__dict__.copy()

class TimestampMixin:
    def __init_subclass__(cls, **kwargs):
        super().__init_subclass__(**kwargs)
        original_init = cls.__init__
        def new_init(self, *args, **kwargs):
            from datetime import datetime
            original_init(self, *args, **kwargs)
            self.created_at = datetime.now().isoformat()
        cls.__init__ = new_init

class User(SerializableMixin, TimestampMixin):
    def __init__(self, name, email):
        self.name = name
        self.email = email

u = User("Veera", "v@test.com")
print(u.to_json())  # {"name": "Veera", "email": "v@test.com", "created_at": "..."}

# ============================================================
# 4. PROXY PATTERN — Lazy loading
# ============================================================
class LazyProperty:
    """Descriptor that computes value on first access."""
    def __init__(self, func):
        self.func = func
        self.attr_name = f"_lazy_{func.__name__}"

    def __get__(self, obj, objtype=None):
        if obj is None:
            return self
        if not hasattr(obj, self.attr_name):
            setattr(obj, self.attr_name, self.func(obj))
        return getattr(obj, self.attr_name)

class DataProcessor:
    def __init__(self, filepath):
        self.filepath = filepath

    @LazyProperty
    def data(self):
        print("Loading data...")  # Only happens once!
        return [1, 2, 3, 4, 5]

# ============================================================
# 5. CHAIN OF RESPONSIBILITY
# ============================================================
class Handler:
    def __init__(self):
        self._next = None

    def set_next(self, handler):
        self._next = handler
        return handler

    def handle(self, request):
        if self._next:
            return self._next.handle(request)
        return None

class AuthHandler(Handler):
    def handle(self, request):
        if not request.get("token"):
            return {"error": "No auth token"}
        return super().handle(request)

class ValidationHandler(Handler):
    def handle(self, request):
        if not request.get("data"):
            return {"error": "No data"}
        return super().handle(request)

class ProcessHandler(Handler):
    def handle(self, request):
        return {"success": True, "data": request["data"]}

# Build chain
auth = AuthHandler()
auth.set_next(ValidationHandler()).set_next(ProcessHandler())

print(auth.handle({"token": "abc", "data": "hello"}))  # success
print(auth.handle({"data": "hello"}))                   # No auth token

# ============================================================
# 6. DESCRIPTOR FOR VALIDATION (Reusable)
# ============================================================
class TypeChecked:
    def __init__(self, expected_type):
        self.expected_type = expected_type

    def __set_name__(self, owner, name):
        self.name = name

    def __get__(self, obj, objtype=None):
        if obj is None: return self
        return getattr(obj, f"_{self.name}", None)

    def __set__(self, obj, value):
        if not isinstance(value, self.expected_type):
            raise TypeError(f"{self.name} must be {self.expected_type.__name__}, got {type(value).__name__}")
        setattr(obj, f"_{self.name}", value)

class Product:
    name = TypeChecked(str)
    price = TypeChecked((int, float))
    quantity = TypeChecked(int)

    def __init__(self, name, price, quantity):
        self.name = name
        self.price = price
        self.quantity = quantity

p = Product("Laptop", 999.99, 10)
# p.price = "free"  # TypeError!
